<script setup lang="ts">
import {ref,onMounted} from 'vue';import {request} from './service';import ImagePicker from './ImagePicker.vue';
const profile=ref(null),life=ref(null),busy=ref(false),message=ref('');
onMounted(async()=>{try{profile.value=await request('/api/studio/profile');life.value=(await request('/api/private/state')).profile;}catch(e){message.value=e.message;}});
async function save(){busy.value=true;message.value='';try{profile.value=await request('/api/studio/profile','PUT',profile.value);window.dispatchEvent(new CustomEvent('lin-theme',{detail:profile.value.theme}));window.dispatchEvent(new Event('lin-appearance'));message.value='空间外观已保存';}catch(e){message.value=e.message;}finally{busy.value=false;}}
</script>
<template><section class="appearance-page"><header><span class="space-eyebrow">MAKE YOURSELF AT HOME</span><h1>我的空间，我的样子。</h1><p>一张清爽的工作桌，或是装满喜欢的私人据点。</p></header><form v-if="profile" @submit.prevent="save"><div class="mood-cards"><button type="button" class="mood-card mood-minimal" :aria-pressed="profile.theme==='minimal'" @click="profile.theme='minimal'"><div class="mood-layout"><i/><div><b>STUDIO / 08</b><span/><span/><span/></div></div><h2>留白 · 工作室</h2><p>侧边导航、紧凑布局、清晰线条，专注创作。</p></button><button type="button" class="mood-card mood-cozy" :aria-pressed="profile.theme==='cozy'" @click="profile.theme='cozy'"><div class="mood-layout" :style="{backgroundImage:'url('+(profile.customWallpaper||'/assets/'+profile.wallpaper+'.webp')+')'}"><b>✦ YOUR SAVE POINT</b><span>今天，也有喜欢的故事。</span></div><h2>私宅 · 存档点</h2><p>全景壁纸、半透明卡片、角色与便签，收藏日常。</p></button></div><section class="appearance-panel"><h2>私宅壁纸</h2><p>只出现在你的私人空间，不会自动公开到博客。</p><ImagePicker v-model="profile.customWallpaper" label="私宅壁纸"/><label>壁纸可见度 <el-slider v-model="profile.wallpaperOpacity" :min="0" :max="70" show-input/></label><label class="appearance-toggle"><el-switch v-model="profile.motion"/>启用空间动效</label></section><footer class="appearance-save"><span role="status">{{message}}</span><el-button type="primary" native-type="submit" :loading="busy">保存空间外观</el-button></footer></form><RouterLink to="/life/settings" class="appearance-more">角色、喜好与日常目标 →</RouterLink></section></template>
<style scoped>.appearance-page{max-width:1080px;margin:auto}.appearance-page h1{font-size:32px;margin:12px 0}.appearance-page p{font-size:13px;line-height:1.8;color:var(--studio-muted)}.mood-cards{display:grid;grid-template-columns:1fr 1fr;gap:24px;margin:28px 0}.mood-card{text-align:left;background:var(--studio-panel);border:2px solid var(--studio-line);padding:18px;border-radius:12px;color:inherit;cursor:pointer}.mood-card[aria-pressed=true]{border-color:#917bab;box-shadow:0 0 0 3px #917bab16}.mood-card h2{font-size:20px;margin:19px 0 5px}.mood-layout{height:180px;border-radius:7px;overflow:hidden}.mood-minimal .mood-layout{background:#f0f2f5;display:flex;gap:20px;padding:16px}.mood-minimal .mood-layout>i{background:#272d3c;width:35px;border-radius:5px}.mood-minimal .mood-layout>div{flex:1}.mood-minimal .mood-layout b{display:block;font:11px monospace;color:#606879;margin:8px}.mood-minimal .mood-layout span{display:block;height:26px;background:white;margin:10px 0;border:1px solid #e1e5ea}.mood-cozy .mood-layout{background-size:cover;background-position:center;padding:26px;color:white;text-shadow:0 2px 10px #111}.mood-cozy .mood-layout b{display:block;font:10px monospace;letter-spacing:2px;margin-top:24px}.mood-cozy .mood-layout span{display:inline-block;margin-top:25px;padding:12px;background:#fff6;color:#222;backdrop-filter:blur(10px);border-radius:8px;text-shadow:none;font-size:13px}.appearance-panel{padding:28px;background:var(--studio-panel);border:1px solid var(--studio-line);border-radius:12px}.appearance-panel h2{font-size:21px}.appearance-panel>label{display:block;margin-top:26px;font-size:13px}.appearance-panel .appearance-toggle{display:flex;gap:15px;align-items:center}.appearance-save{display:flex;justify-content:space-between;align-items:center;gap:15px;padding:24px 0;font-size:12px}.appearance-more{display:block;margin:12px 0;font-size:13px}@media(max-width:700px){.mood-cards{grid-template-columns:1fr}.appearance-page h1{font-size:26px}.appearance-panel{padding:20px}}
